  ('memory/storage-replacement-and-pairing', 'memory', 'storage-replacement-and-pairing', 5, 'Storage replacement and pairing', 'Why storage swaps often need programming, or aren''t possible.', 10, 'advanced', 'planned', '{}'::text[], '[]'::jsonb),
