  ('buses/mipi-dsi-and-csi', 'buses', 'mipi-dsi-and-csi', 2, 'MIPI display and camera interfaces', 'High-speed links to the screen and cameras.', 10, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
  ('buses/interrupts-and-gpio', 'buses', 'interrupts-and-gpio', 3, 'Interrupts and GPIO', 'How peripherals get the SoC''s attention.', 8, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
