  ('buses/rf-front-end-basics', 'buses', 'rf-front-end-basics', 5, 'RF front-end basics', 'Transceiver, amplifiers, switches and antennas.', 14, 'advanced', 'planned', '{}'::text[], '[]'::jsonb),
  ('buses/audio-interfaces', 'buses', 'audio-interfaces', 6, 'Audio interfaces', 'How audio travels between SoC, codec and amplifiers.', 10, 'intermediate', 'planned', '{}'::text[], '[]'::jsonb),
