insert into public.quizzes (lesson_id, questions) values
  ('fundamentals/voltage-current-resistance', '[{"id":"q1","prompt":"A component has 3 V across it and 0.5 A flowing through it. What is its resistance?","options":["1.5 Ω","6 Ω","3.5 Ω","0.17 Ω"],"correctIndex":1,"explanation":"R = V ÷ I = 3 ÷ 0.5 = 6 Ω."},{"id":"q2","prompt":"A capacitor on a supply line fails short. What happens to the current on that line?","options":["It drops to zero","It rises sharply","It stays the same","It reverses direction"],"correctIndex":1,"explanation":"A short is a very low resistance, and I = V ÷ R. As R gets very small, current rises sharply. That is why shorted parts often get hot."},{"id":"q3","prompt":"Voltage is always measured…","options":["At a single point","Between two points","Only across batteries","In series with the load"],"correctIndex":1,"explanation":"Voltage is a difference between two points. On a board, one of them is usually ground."}]'::jsonb),
  ('fundamentals/multimeter-basics', '[{"id":"q1","prompt":"Which measurement requires the board to be powered?","options":["Resistance","Continuity","DC voltage","Diode mode"],"correctIndex":2,"explanation":"Voltage only exists while the circuit is powered. Resistance, continuity and diode mode must be done with the board unpowered."},{"id":"q2","prompt":"You measure resistance on a board with the battery still connected. The reading is…","options":["Accurate","Unreliable, and you may damage the meter or board","Always zero","Accurate only on ground points"],"correctIndex":1,"explanation":"The meter applies its own voltage in resistance mode. The board''s own power interferes with it, so the reading is meaningless and can cause damage."},{"id":"q3","prompt":"Why should you record the phone''s state (off, booting, charging) with each voltage reading?","options":["The meter needs it to calculate","Rails can switch on and off depending on the state","Voltage is always the same, so it doesn''t matter","It changes the meter''s range"],"correctIndex":1,"explanation":"Many rails are only present in certain states. A reading without its state can''t be compared fairly with a known-good board."}]'::jsonb),
  ('fundamentals/diode-mode', '[{"id":"q1","prompt":"In diode mode, a reading very close to zero between a line and ground means…","options":["The line is healthy","The line is shorted or nearly shorted to ground","The line is open","The meter''s battery is flat"],"correctIndex":1,"explanation":"Almost no voltage is needed to push the test current, so there is a very low-resistance path to ground: a short."},{"id":"q2","prompt":"What is the correct diode-mode reading for a phone''s main supply line?","options":["Always 400 mV","Always OL","There is no universal value. Compare with a known-good board of the same model, same meter and same orientation","Whatever value the battery is labelled with"],"correctIndex":2,"explanation":"Readings depend on the board, the meter and the probe orientation, so only a like-for-like comparison is meaningful."},{"id":"q3","prompt":"Why should you record which probe orientation you used?","options":["The two orientations give different readings","The meter requires it","The red probe must always be positive","It only matters on Apple boards"],"correctIndex":0,"explanation":"Swapping the probes measures the path in the other direction, which usually gives a different value."}]'::jsonb),
  ('power/power-path', '[{"id":"q1","prompt":"Why are there usually inductors (coils) close to the PMIC?","options":["They store the battery charge","Buck converters use them to step voltage down efficiently","They protect against liquid damage","They generate the clock signal"],"correctIndex":1,"explanation":"Buck converters switch rapidly and store energy in an inductor on each cycle. That is what makes them efficient."},{"id":"q2","prompt":"A short on the main system supply line commonly shows on a bench supply as…","options":["No current at all, ever","Current as soon as the supply is connected, before pressing power","Normal boot current","Current only while charging"],"correctIndex":1,"explanation":"The main supply line is live whenever power is connected, so a short on it draws current before the phone is even switched on."},{"id":"q3","prompt":"Where should you get the name and expected voltage of a rail?","options":["From any phone with the same chipset","From this lesson","From that model''s schematic or a known-good board of the same model","Rails are the same on every phone"],"correctIndex":2,"explanation":"Rail names and values vary by platform, model and board revision."}]'::jsonb),
  ('power/dc-power-supply-current-draw', '[{"id":"q1","prompt":"Current flows the moment you connect the supply, before pressing power. What does this most commonly suggest?","options":["A healthy phone","A short on the main supply line or something connected to it","A faulty display","A software problem"],"correctIndex":1,"explanation":"Nothing should draw significant current before power-on, so current at connection usually means a short on a line that is always live."},{"id":"q2","prompt":"Why start with a low current limit?","options":["It makes the phone boot faster","It limits damage and heat if there is a short","The phone needs low current to start","It is required for diode mode"],"correctIndex":1,"explanation":"If there is a short, a low limit restricts how much energy flows into it."},{"id":"q3","prompt":"What is the best reference for a normal current pattern?","options":["Any phone with the same chipset","A known-good phone of the same model","The battery label","This lesson"],"correctIndex":1,"explanation":"Normal current behaviour differs between models, so compare like with like."}]'::jsonb),
  ('boot/what-happens-when-you-press-power', '[{"id":"q1","prompt":"What runs first on the SoC after it is released from reset?","options":["The operating system","The boot ROM","The display driver","The bootloader from storage"],"correctIndex":1,"explanation":"The boot ROM is built into the SoC and always runs first. It then loads the first bootloader from storage."},{"id":"q2","prompt":"A phone is only detected by a computer in an emergency download mode. Which areas are the most likely suspects?","options":["Display and touch","Storage, its supply, or firmware","Speaker and microphone","The SIM reader"],"correctIndex":1,"explanation":"The boot ROM is running (that is what provides the download mode), but it can''t load a bootloader. That points to storage, its power or interface, or the firmware."},{"id":"q3","prompt":"Which order is correct?","options":["Boot ROM → power key → rails → OS","Power key → rails → clocks and reset release → boot ROM → bootloaders → OS","Rails → OS → boot ROM → bootloaders","Bootloaders → boot ROM → rails → OS"],"correctIndex":1,"explanation":"Power must be up and stable, with clocks running and reset released, before the SoC can run its boot ROM, which then loads the bootloaders and finally the OS."}]'::jsonb),
  ('clocks/crystals-and-oscillators', '[{"id":"q1","prompt":"What does a clock signal do for a digital chip?","options":["It supplies the chip''s power","It sets the pace of the chip''s steps","It stores the time and date","It carries data to memory"],"correctIndex":1,"explanation":"A clock is a steady timing signal. Digital chips do their work in steps, and the clock sets when each step happens."},{"id":"q2","prompt":"A passive crystal shows no clock. Which of these could be the cause?","options":["Only the crystal itself","The crystal, its load capacitors, or the chip that drives it (and its supply)","Only the battery","The display connector"],"correctIndex":1,"explanation":"A crystal can''t oscillate on its own. The drive circuit lives in another chip, so that chip and its supply are suspects too, along with the crystal and its load capacitors."},{"id":"q3","prompt":"Why do radio sections often use temperature-compensated oscillators?","options":["They use less power than any other part","Radio frequencies must stay accurate as temperature changes","They replace the need for a PMIC","They store calibration data for the IMEI"],"correctIndex":1,"explanation":"Crystal frequency drifts slightly with temperature. Radios need an accurate frequency, so a TCXO corrects for that drift."}]'::jsonb),
  ('clocks/rtc-and-sleep-clock', '[{"id":"q1","prompt":"Why is 32.768 kHz used for the sleep clock?","options":["It is the fastest frequency a crystal can make","It divides down to exactly one tick per second with a simple counter","It matches the mobile network frequency","It is required by the USB standard"],"correctIndex":1,"explanation":"32,768 is 2¹⁵, so halving it 15 times gives exactly 1 Hz: one tick per second, with very little circuitry and power."},{"id":"q2","prompt":"How can a sleep clock fault make a phone look dead?","options":["It drains the battery instantly","On some designs the PMIC needs it before completing power-on","It disables the display backlight only","It locks the bootloader"],"correctIndex":1,"explanation":"On some designs the PMIC waits for the sleep clock as part of power-on. Without it, the sequence stops early and the phone appears dead."},{"id":"q3","prompt":"A phone shows the wrong time after starting up. What''s the best first conclusion?","options":["The RTC crystal is definitely faulty","It may be a setting or software issue; suspect the RTC mainly if time resets whenever power is lost","The PMIC must be replaced","The main reference clock is missing"],"correctIndex":1,"explanation":"Running phones usually take their time from the network or internet. A hardware RTC fault typically shows as the time resetting every time power is lost."}]'::jsonb),
  ('clocks/reset-signals', '[{"id":"q1","prompt":"Why is a chip held in reset during power-on?","options":["To save battery while charging","Its internal state is unpredictable until supplies and clocks are ready","To erase its firmware","To test the display"],"correctIndex":1,"explanation":"Reset holds the chip in a known state until supplies (and, often, clocks) are stable. Releasing it lets the chip start properly."},{"id":"q2","prompt":"A reset line on the schematic is named with an _N suffix. What does that usually mean?","options":["It is not connected","It is active-low: the chip is held in reset while the line is low","It carries a clock signal","It only works when charging"],"correctIndex":1,"explanation":"_N, _B or a bar over the name usually marks an active-low signal. Low means \"in reset\"; high means released."},{"id":"q3","prompt":"What does a watchdog do if software stops responding?","options":["Turns off the display","Restarts the system when its timer runs out","Charges the battery faster","Deletes user data"],"correctIndex":1,"explanation":"Software must keep restarting the watchdog timer. If it hangs, the timer runs out and the watchdog restarts the system. A repeating hang can show as a boot loop."}]'::jsonb),
  ('clocks/diagnosing-clock-faults', '[{"id":"q1","prompt":"What should you check before blaming a clock or reset fault?","options":["The camera modules","The supplies the clock and reset circuits depend on","The phone''s software version","The SIM card"],"correctIndex":1,"explanation":"Oscillators and the chips that drive crystals need power, and resets often wait for rails. A missing supply can look exactly like a clock or reset fault."},{"id":"q2","prompt":"A multimeter shows a steady DC voltage on a clock line. What does that prove?","options":["The clock is running at the correct frequency","Nothing about whether it''s oscillating correctly; it''s only an average","The crystal is faulty","The reset line is released"],"correctIndex":1,"explanation":"A multimeter averages the signal. It can''t show frequency or whether the clock is actually oscillating. An oscilloscope is needed to confirm that."},{"id":"q3","prompt":"Why can probing a crystal''s pins give a misleading result?","options":["The probe adds capacitance that can shift or stop the oscillation","Crystals only work when the phone is charging","The probe erases the PMIC''s firmware","Crystals produce high voltage that damages meters"],"correctIndex":0,"explanation":"Crystal circuits are sensitive to added capacitance. A probe can change or stop the oscillation, so use a 10× probe and a buffered output where possible."}]'::jsonb)
insert into public.game_scenarios (id, title, symptom, difficulty, brief, device, debrief, related_lesson_ids, related_blocks) values
  ('dead-after-charge', 'The phone that died on the charger', 'No power, no response', 'beginner', '“I left it charging overnight with a cheap fast charger I bought at the market. In the morning it was completely dead. Nothing happens when I press power or plug it in.”', 'Simulated Android phone. Not a real model.', '{"rootCause":"In this simulation, the charging IC failed short and pulled the main supply line to ground. The short cleared when the IC was removed. The unbranded charger fits the history, but nothing here proves it caused the failure.","alternatives":["A shorted capacitor on the main supply line: same current pattern. Locating the hot spot separates it from the charging IC.","A shorted load fed directly from the main supply line: same pattern, a different hot spot.","A flat or failed battery: ruled out because the board drew current from the bench supply with no battery fitted.","No power-on signal reaching the power-management circuit: would show no current at all, not current before power-on."],"commonMistakes":["Replacing the PMIC because the phone is dead.","Raising the current limit to ''push through'' a short.","Treating a hot spot as proof without confirming it.","Fitting a part that only matches the footprint.","Returning the phone after it boots, without testing charging."],"lessons":["Start with history and cheap checks before any test that could cause damage.","Current before pressing power points to a short on a line that is always live.","Confirm a short in diode mode with the board unpowered, then locate it before replacing anything.","A hot spot is strong evidence, not proof. Confirm it, for example by checking whether the short clears with the part removed.","Keep cause and correlation apart: the charger fits the story, but it isn''t proven.","Verify after the repair: no short, normal current pattern, charging and boot."]}'::jsonb, array['power/dc-power-supply-current-draw', 'fundamentals/diode-mode', 'power/power-path']::text[], array['charging', 'pmic']::text[]),
  ('logo-loop', 'Stuck at the logo', 'Boot loop after a drop', 'intermediate', '“I dropped it on the floor yesterday. Now it shows the logo, goes black, shows the logo again, over and over. Please don''t lose my photos.”', 'Simulated Android phone with stacked memory. Not a real model.', '{"rootCause":"In this simulation, the drop cracked solder joints under the stacked memory. It stayed a hypothesis until the rework produced stable boots and a clean tool log, which confirmed it.","alternatives":["Corrupted firmware: same loop. Ruled out when the correct firmware was flashed and the loop continued.","A worn battery sagging under load: ruled out by looping on the bench supply.","A wrong loader in the flashing tool: can report a memory error on a healthy phone. Ruled out by confirming the loader.","A missing RAM supply rail: ruled out by comparing the rails with a known-good board.","An SoC fault: can''t be fully excluded by these tests, but the successful rework points away from it."],"commonMistakes":["Flashing first and wiping data the customer wanted to keep.","Treating a memory error message as proof the RAM is faulty.","Heating the SoC or memory without preparation.","Promising a guaranteed repair while the cause is still a hypothesis.","Calling it fixed after one good boot."],"lessons":["Agree on data risk with the customer before any step that could erase it.","A bench supply rules out the battery and shows the boot pattern in one test.","Read-only tool logs can show where boot fails without touching user data.","A memory initialisation error is not proof that the RAM is faulty.","Label conclusions honestly: a likely cause is a hypothesis until the repair confirms it.","Verify intermittent faults with repeated boots and warm running."]}'::jsonb, array['boot/what-happens-when-you-press-power', 'power/dc-power-supply-current-draw']::text[], array['ram', 'storage', 'soc']::text[]),
  ('no-wifi', 'Wi-Fi won''t switch on', 'Wi-Fi toggle greyed out', 'advanced', '“It fell out of my pocket on the bus. Everything works except Wi-Fi: the switch is greyed out. Bluetooth won''t turn on either.”', 'Simulated Android phone. In this simulation the Wi-Fi/Bluetooth IC has its own crystal. Real designs vary.', '{"rootCause":"In this simulation, the drop cracked the crystal feeding the Wi-Fi/Bluetooth IC, so the IC had power but no clock. The clock returning after the crystal was replaced confirmed it.","alternatives":["A software or firmware fault: can grey out the switch. Ruled out first by the software checks.","A damaged antenna or antenna cable: usually gives weak signal, not a greyed-out switch.","A stuck reset line: same symptom with power and clock present. Checked and found as expected.","A failed Wi-Fi IC: possible, but it can''t start without a clock anyway. The clock returning and Wi-Fi working ruled it out."],"commonMistakes":["Replacing the antenna for a greyed-out switch.","Factory resetting before trying less drastic checks.","Trying to confirm a clock with a multimeter.","Replacing the Wi-Fi IC before checking its clock and reset.","Fitting a crystal that only matches the footprint."],"lessons":["Two features failing together often point at a shared part.","Rule out software first, without touching the customer''s data.","An IC needs power, clock and reset. Check each one; finding a fault in one doesn''t clear the others.","A multimeter can''t confirm a clock. Use an oscilloscope.","Follow a missing signal back to its source before replacing the IC that needs it.","Confirm the cause after the repair: the clock should be present again before you test Wi-Fi."]}'::jsonb, array['clocks/crystals-and-oscillators', 'clocks/diagnosing-clock-faults', 'clocks/reset-signals']::text[], array['connectivity', 'clock']::text[])
insert into public.game_steps (scenario_id, position, step_key, prompt, choices) values
  ('dead-after-charge', 0, 'intake', 'The phone is on your bench. Before touching it with tools, what do you do?', '[{"id":"history","label":"Get the full history: the charger used, any liquid, drops, previous repairs, and whether it was fine before","quality":"best","feedback":"History costs nothing and often points straight at the fault area. Here it tells you power came in through the USB side just before it died.","finding":"Unbranded fast charger used overnight. No liquid, drops or previous repairs. It worked normally the evening before."},{"id":"flash","label":"Flash new firmware","quality":"poor","feedback":"A phone with no sign of life won''t be detected by a computer, so it can''t be flashed. Firmware comes later, once you know the board powers up."},{"id":"wake-up","label":"Apply a high current to the battery connector to ''wake it up''","quality":"unsafe","feedback":"If something is shorted, high current can burn the board and destroy the evidence you need. Always start with a low current limit."}]'::jsonb),
  ('dead-after-charge', 1, 'inspect', 'Which inspection comes first?', '[{"id":"visual","label":"Open it and inspect under magnification: battery condition, battery connector, USB port and the charging area for heat marks or damage","quality":"best","feedback":"A visual check can find burn marks, a swollen battery or a damaged port before any test. Nothing visible doesn''t mean nothing wrong, but it''s worth knowing.","finding":"Battery not swollen. Port and connector clean. No visible burn marks or corrosion."},{"id":"known-good","label":"Try a known-good battery and a known-good charger first","quality":"ok","feedback":"A sensible, cheap check that rules out the battery and charger. You skipped the visual inspection, which can catch a swollen battery or burn mark before you connect anything.","finding":"No change with a known-good battery and charger."},{"id":"swap-port","label":"Replace the charging port flex","quality":"poor","feedback":"That''s a part swap with no evidence behind it. The phone doesn''t respond to the power key either, so the port alone wouldn''t explain everything."}]'::jsonb),
  ('dead-after-charge', 2, 'first-test', 'What''s your first electrical test?', '[{"id":"bench","label":"Disconnect the battery. Connect a bench power supply with a low current limit and watch the current before pressing power","quality":"best","feedback":"The current pattern on a bench supply is one of the fastest ways to narrow down a dead phone, and the low limit protects the board.","finding":"Current flows the moment the supply is connected, before the power key is pressed, and sits at the limit you set.","reading":{"label":"Bench supply current, battery removed","value":"Rises immediately on connection and sits at the current limit","reference":"A healthy phone draws almost no current before power is pressed"},"next":"interpret"},{"id":"battery-voltage","label":"Measure the battery voltage at the connector with a multimeter","quality":"ok","feedback":"A reasonable quick check, but a voltage reading can''t show whether something is drawing current it shouldn''t.","finding":"Battery voltage is present at the connector.","next":"battery-result"},{"id":"hold-power","label":"Hold the power key for longer with the charger connected","quality":"poor","feedback":"You''ve already seen that it doesn''t respond. Repeating the same action gives no new information."}]'::jsonb),
  ('dead-after-charge', 3, 'battery-result', 'What does that reading tell you?', '[{"id":"only-voltage","label":"Only that the battery holds charge and reaches the connector. It says nothing about whether the board is drawing current it shouldn''t","quality":"best","feedback":"Right. Voltage being present is a starting point, not a diagnosis. A bench supply would show what the board does with that power.","interpretation":{"supports":"The battery holds charge and the connector makes contact.","doesNotProve":"That the board is healthy, or that nothing is shorted. A short can sit behind a perfectly good battery voltage.","remaining":["A short on a line that''s always live","No power-on signal reaching the power-management circuit","A fault further along the start-up sequence"]}},{"id":"battery-fine-board-fine","label":"The battery is fine, so the fault must be software","quality":"poor","feedback":"A good battery doesn''t make the board good. A phone with no response at all isn''t showing a software fault yet."}]'::jsonb),
  ('dead-after-charge', 4, 'bench-after-battery', 'You need to see what the board does with power. What next?', '[{"id":"bench","label":"Disconnect the battery. Connect a bench power supply with a low current limit and watch the current before pressing power","quality":"best","feedback":"This is the test that shows whether current flows when it shouldn''t.","finding":"Current flows the moment the supply is connected, before the power key is pressed, and sits at the limit you set.","reading":{"label":"Bench supply current, battery removed","value":"Rises immediately on connection and sits at the current limit","reference":"A healthy phone draws almost no current before power is pressed"}},{"id":"replace-battery","label":"Replace the battery anyway","quality":"poor","feedback":"The battery voltage was fine. Swapping it adds cost and teaches you nothing new."}]'::jsonb),
  ('dead-after-charge', 5, 'interpret', 'What does this result support, and what doesn''t it prove?', '[{"id":"always-live-short","label":"Something on a line that''s always live is shorted, most likely the main supply line or a part on it. It doesn''t tell me which part","quality":"best","feedback":"Exactly. Before power-on, only always-live lines should be connected to the supply, so current here points to a short on one of them.","interpretation":{"supports":"A short, or near-short, on a line that''s live before power-on. On most designs that''s the main supply line and what''s connected to it.","doesNotProve":"Which part is shorted. A current reading points at a line, never at one component.","remaining":["A shorted capacitor on the main supply line","A failed charging IC","Another load fed directly from the main supply line","Less likely: the input stage of the power-management IC"]}},{"id":"pmic-dead","label":"The PMIC has failed","quality":"poor","feedback":"Too early. A current pattern can''t name a component. Many parts sit on the same line, and the PMIC is only one of them."},{"id":"bad-battery","label":"The battery is bad","quality":"poor","feedback":"The battery wasn''t connected: the bench supply replaced it, and the current still flowed. The fault is on the board."}]'::jsonb),
  ('dead-after-charge', 6, 'circuit', 'Which line is live before the power key is pressed?', '[{"id":"main-line","label":"The main system supply line, and the parts connected straight to it, including the charging circuit","quality":"best","feedback":"Right. It''s fed directly from the battery side, so it''s live whenever power is connected. That makes it the first line to check."},{"id":"pmic-rails","label":"The PMIC''s output rails","quality":"poor","feedback":"Most PMIC output rails stay off until the power key starts the sequence, so they''re unlikely to draw current yet. Some designs have always-on outputs, and the schematic shows which, but the main supply line comes first."},{"id":"display-rails","label":"The display supplies","quality":"poor","feedback":"Display supplies come from the PMIC or dedicated ICs and switch on during start-up. They aren''t live before power-on."}]'::jsonb),
  ('dead-after-charge', 7, 'confirm-short', 'How do you confirm the short safely?', '[{"id":"diode","label":"Disconnect all power, then check the main supply line to ground in diode mode, and compare with a known-good board","quality":"best","feedback":"Diode mode works with the board unpowered, so it confirms the short without pushing more energy into it.","finding":"The main supply line reads as shorted to ground in diode mode.","reading":{"label":"Diode mode, main supply line to ground","value":"Near zero: shorted","reference":"Known-good board: clearly not shorted"}},{"id":"raise-limit","label":"Raise the current limit until the phone turns on","quality":"unsafe","feedback":"Current before power-on means a short. Raising the limit pushes more energy into it and can damage the board further, or burn away the evidence."},{"id":"every-rail","label":"Check every PMIC output rail in diode mode","quality":"poor","feedback":"That''s a lot of work in the wrong place. The current flows before power-on, so start with the line that''s live then."}]'::jsonb),
  ('dead-after-charge', 8, 'locate', 'Many parts sit on this line. How do you find the shorted one?', '[{"id":"thermal","label":"List the parts on the line from the boardview, inject a limited current at a voltage safe for that line, and look for the warm part with a thermal camera","quality":"best","feedback":"Limited current injection makes the shorted part warm up so you can see it. Keeping the limits low and right for that line protects everything else on it.","finding":"With limited current injected, the charging IC is the clear hot spot on the thermal camera.","reading":{"label":"Thermal camera during limited current injection","value":"Charging IC is the clear hot spot"}},{"id":"rosin","label":"No thermal camera: coat the area in rosin smoke (or use freeze spray), inject a limited current, and watch where it melts or clears first","quality":"best","feedback":"A good method without a thermal camera. It''s slower and less precise, so look closely at parts packed tightly together.","finding":"With limited current injected, the rosin melts first on top of the charging IC."},{"id":"remove-caps","label":"Remove the capacitors on the line one at a time until the short clears","quality":"poor","feedback":"This can work, but it''s slow, risks lifting pads, and the short may not be a capacitor at all. Locate it first."},{"id":"full-voltage","label":"Inject at full battery voltage with no current limit to find it faster","quality":"unsafe","feedback":"With no limit, the short can draw enough current to burn the part, lift pads or damage the board. Always inject with a limited current."}]'::jsonb),
  ('dead-after-charge', 9, 'confirm-cause', 'Is that enough to be sure it''s the cause?', '[{"id":"isolate","label":"Remove the charging IC, then check the main supply line in diode mode again","quality":"best","feedback":"If the short clears with the part removed, the part was causing it. You''d be replacing it anyway, so removing it costs nothing extra.","finding":"With the charging IC removed, the main supply line is no longer shorted.","reading":{"label":"Diode mode, main supply line to ground, charging IC removed","value":"No longer shorted; comparable to the known-good board","reference":"Known-good board: clearly not shorted"}},{"id":"replace-now","label":"Yes: fit a new charging IC straight away","quality":"poor","feedback":"Not yet. A hot spot is strong evidence, but heat can also come from a part right next to the real short, or from the path the current takes. Confirm first."},{"id":"replace-both","label":"Replace the charging IC and the PMIC together, to be safe","quality":"poor","feedback":"Nothing points at the PMIC. Replacing parts without evidence costs money, adds risk and hides what the real fault was."}]'::jsonb),
  ('dead-after-charge', 10, 'repair', 'How do you fit the replacement?', '[{"id":"correct-part","label":"Fit the exact part for this model and board revision (from the parts list or schematic) with proper flux and heat control, then recheck the line in diode mode before applying any power","quality":"best","feedback":"The right part, fitted carefully, then checked before power goes in. A new short from a solder bridge is caught before it can do damage.","finding":"New charging IC fitted. The main supply line is not shorted in diode mode."},{"id":"same-footprint","label":"Fit any charging IC that has the same footprint","quality":"poor","feedback":"Same size doesn''t mean same part. A different IC can have different pin functions or settings, and may not work or may damage the board. Use the exact part."},{"id":"power-straight-away","label":"Fit it, then plug in the customer''s charger to test it","quality":"unsafe","feedback":"Check for shorts before applying power. And the customer''s unbranded charger is a suspect in this failure, so test with a known-good charger."}]'::jsonb),
  ('dead-after-charge', 11, 'verify', 'What do you check before returning the phone?', '[{"id":"full-check","label":"Normal current pattern on the bench supply, a full boot, charging with a known-good charger and cable, and a check that the battery percentage rises","quality":"best","feedback":"That confirms the original fault is gone and the repaired area works under load. Tell the customer the unbranded charger fits the history, so it''s worth replacing.","finding":"Normal current pattern, full boot, and charging works with a known-good charger.","next":"end"},{"id":"boots","label":"It boots, so it''s fixed","quality":"poor","feedback":"Booting proves part of it. The fault was on the charging side, so you must also check that it charges, and that the current pattern is normal."}]'::jsonb),
  ('logo-loop', 0, 'intake', 'Before you start, what do you do?', '[{"id":"history-and-data","label":"Get the history (drop, liquid, updates, earlier faults) and agree with the customer which steps could erase their data before doing any of them","quality":"best","feedback":"History points you at the fault area, and agreeing on data risk up front means you won''t wipe photos the customer asked you to keep.","finding":"Dropped on a tiled floor yesterday. No liquid, no recent updates, worked fine before. The customer agrees to data-risking steps only if nothing else works."},{"id":"screen","label":"Replace the screen","quality":"poor","feedback":"The logo displays correctly, so the screen works. The problem is that boot never finishes."},{"id":"hot-air","label":"Heat the SoC and memory with hot air to reflow them","quality":"unsafe","feedback":"Unprepared heating can damage the SoC, memory and nearby parts, and makes a proper repair harder. Reflow and reballing are planned, advanced procedures, and you have no evidence yet."}]'::jsonb),
  ('logo-loop', 1, 'inspect', 'What do you inspect first?', '[{"id":"impact","label":"Inspect the frame for the impact point, then open it and check connectors, battery and the board near the impact under magnification","quality":"best","feedback":"Finding where the force went tells you which parts of the board took the shock. Unseated connectors and a damaged battery are quick to rule out.","finding":"A dent on one corner of the frame, near the SoC and memory area. Connectors are seated, the battery isn''t swollen, and nothing is visibly cracked."},{"id":"battery-swap","label":"Replace the battery straight away","quality":"poor","feedback":"Not yet. A worn battery can cause restarts under load, but you can test that without buying a part. Inspect first."}]'::jsonb),
  ('logo-loop', 2, 'first-test', 'What''s your first electrical test?', '[{"id":"bench","label":"Power it from a bench supply instead of the battery and watch the current through a few boot attempts","quality":"best","feedback":"This replaces the battery, so if it still loops the battery isn''t the cause, and the current pattern shows how far each attempt gets.","finding":"On the bench supply the phone still loops. Current rises and varies as if booting, then drops back, and the cycle repeats.","reading":{"label":"Bench supply current during boot attempts","value":"Rises and varies, drops back, repeats"},"next":"interpret"},{"id":"known-good-battery","label":"Fit a known-good battery and try again","quality":"ok","feedback":"It tests the battery, but the bench supply would have done that and shown the current pattern too.","finding":"Still loops with a known-good battery.","next":"battery-result"},{"id":"flash-now","label":"Flash the full firmware straight away","quality":"poor","feedback":"A full flash usually erases the user''s data, and the customer asked you to keep their photos. Gather non-destructive evidence first."}]'::jsonb),
  ('logo-loop', 3, 'battery-result', 'What does that tell you?', '[{"id":"battery-out","label":"The battery is unlikely to be the cause, but I still don''t know where in the boot it fails","quality":"best","feedback":"Right. The battery is mostly ruled out. To narrow it further you need to know how far boot gets.","interpretation":{"supports":"The original battery isn''t causing the loop.","doesNotProve":"Anything about where boot fails, or which part is at fault.","remaining":["Corrupted firmware","Storage or RAM fault","A missing or unstable supply rail","Damaged solder joints from the drop"]},"next":"circuit"},{"id":"must-be-software","label":"Then it must be software","quality":"poor","feedback":"Ruling out the battery doesn''t make it software. A drop can damage hardware in ways that look exactly like a software loop."}]'::jsonb),
  ('logo-loop', 4, 'interpret', 'What does this pattern support, and what doesn''t it prove?', '[{"id":"loop-many-causes","label":"It''s a boot loop that starts each time and fails part-way. The battery is ruled out, but firmware, storage, RAM or power could all cause it","quality":"best","feedback":"Exactly. The board powers up and starts booting every time, so the early stages work. The pattern alone can''t name the cause.","interpretation":{"supports":"Power-on, clocks and reset work well enough to start booting. The battery isn''t the cause.","doesNotProve":"Whether the cause is firmware or hardware, or which part.","remaining":["Corrupted firmware","Storage fault","RAM or its solder joints","A supply rail that drops out under load"]}},{"id":"ram-dead","label":"The RAM is dead","quality":"poor","feedback":"Too early. Nothing so far points at the RAM specifically. Firmware, storage and power produce the same pattern."},{"id":"no-power","label":"The board isn''t getting power","quality":"poor","feedback":"The current rises and the logo appears every cycle, so power is arriving. The fault is later in the boot."}]'::jsonb),
  ('logo-loop', 5, 'circuit', 'The logo appears, then it restarts. Roughly where in the sequence is it failing?', '[{"id":"late","label":"Late: power-on, clocks, reset and the boot ROM have worked. It fails during the bootloaders or as the OS starts, where storage and RAM are needed","quality":"best","feedback":"Right. That places the fault where storage, RAM and firmware are all in play, and it''s why the next step is to get evidence from that stage."},{"id":"power-key","label":"At the power key stage","quality":"poor","feedback":"If it failed at the power key, nothing would happen at all. Here the phone starts booting every cycle."},{"id":"boot-rom","label":"In the boot ROM, before anything else runs","quality":"poor","feedback":"A logo on screen means code beyond the boot ROM is already running. The fault comes later."}]'::jsonb),
  ('logo-loop', 6, 'evidence', 'How do you find out what fails, without risking the photos?', '[{"id":"read-log","label":"Connect the phone to the correct flashing tool for this exact model and use its read-only identify function, then read the log","quality":"best","feedback":"Reading doesn''t write anything, so the data is safe, and tool logs often show which stage fails.","finding":"The tool log reports a memory initialisation error during early boot.","reading":{"label":"Flashing tool log (read-only)","value":"Memory initialisation error"}},{"id":"flash-anyway","label":"Flash the full firmware: it fixes most boot loops","quality":"poor","feedback":"It may well be firmware, but a full flash usually erases the photos you agreed to protect. Get the non-destructive evidence first."},{"id":"microscope-again","label":"Look under the microscope again","quality":"poor","feedback":"You''ve already inspected and found nothing visible. Damage under a stacked package can''t be seen from above. You need electrical evidence now."}]'::jsonb),
  ('logo-loop', 7, 'memory-error', 'What do you check before blaming the RAM?', '[{"id":"loader-and-rails","label":"Confirm the tool''s loader matches the exact model, then check the RAM supply rails against the schematic or a known-good board","quality":"best","feedback":"A wrong loader and a missing supply are both common causes of this error, and both are quick to rule out.","finding":"The loader is correct for this model. The RAM supply rails are present and comparable to the known-good board.","reading":{"label":"RAM supply rails during a boot attempt","value":"Present","reference":"Known-good board: present and comparable"}},{"id":"replace-ram","label":"Replace the RAM: the tool says it''s a memory error","quality":"poor","feedback":"A memory error doesn''t prove the RAM is faulty. Wrong loaders, missing supplies and solder faults cause the same message."}]'::jsonb),
  ('logo-loop', 8, 'confirm', 'Is firmware ruled out yet?', '[{"id":"flash-with-consent","label":"Not yet. Explain that this is now the last step before an invasive repair, get the customer''s agreement to lose data, then flash the correct firmware","quality":"best","feedback":"Flashing is the test that separates firmware from hardware. Now the customer understands why it''s needed and has agreed to the data loss.","finding":"The flash completes, but the phone still loops with the same memory error. Firmware is ruled out."},{"id":"skip-flash","label":"Yes, it must be hardware after a drop. Go straight to memory rework","quality":"poor","feedback":"The drop makes hardware likely, but likely isn''t proven. Rework is risky and expensive; rule out firmware first."}]'::jsonb),
  ('logo-loop', 9, 'repair', 'What do you tell the customer, and what do you offer?', '[{"id":"hypothesis","label":"Explain that cracked solder joints under the stacked memory are the likely cause, not yet proven. Offer an advanced memory rework, with its risks and that it may not succeed, and proceed only if they agree","quality":"best","feedback":"Honest and accurate: the evidence fits, but only a successful rework confirms it. The customer can make an informed choice.","finding":"The customer agrees. Memory rework carried out."},{"id":"promise","label":"Tell them it''s definitely the RAM and the repair is guaranteed","quality":"poor","feedback":"You can''t promise that. The evidence points at the memory joints, but it''s still a hypothesis, and rework can fail."},{"id":"blast","label":"Reflow the memory with hot air, without preparation, to save time","quality":"unsafe","feedback":"Unprepared heating can damage the SoC, memory and neighbouring parts, and can make the board unrepairable. Rework needs proper preparation and heat control."}]'::jsonb),
  ('logo-loop', 10, 'verify', 'How do you confirm the repair before returning the phone?', '[{"id":"stress","label":"Several full boots and restarts, a period of normal use with demanding apps until it''s warm, and the tool log no longer showing the memory error","quality":"best","feedback":"Repeated boots and warm running are where a marginal joint would show itself. A clean log confirms the original error is gone.","finding":"It boots fully every time, stays stable when warm, and the tool no longer reports a memory error. The rework confirmed the cause.","next":"end"},{"id":"one-boot","label":"It booted once, so it''s fixed","quality":"poor","feedback":"A loop can be intermittent, especially with solder faults. Test repeated boots and warm running before you call it fixed."}]'::jsonb),
  ('no-wifi', 0, 'intake', 'Where do you start?', '[{"id":"history","label":"Get the history: when it started, the drop, any liquid, updates or app installs around the same time","quality":"best","feedback":"Wi-Fi and Bluetooth often share one IC on phones, so both failing together after a drop is a strong clue. History also tells you whether a software change could explain it.","finding":"Both stopped right after the drop two days ago. No liquid, no updates or new apps since."},{"id":"sim","label":"Replace the SIM card","quality":"poor","feedback":"The SIM is for mobile service, which works. It has nothing to do with Wi-Fi or Bluetooth."},{"id":"antenna","label":"Replace the Wi-Fi antenna","quality":"poor","feedback":"A bad antenna usually gives weak signal, not a greyed-out switch. And it wouldn''t explain Bluetooth."}]'::jsonb),
  ('no-wifi', 1, 'software', 'Before opening the phone, what do you check?', '[{"id":"soft-checks","label":"Restart, try safe mode, and reset network settings (it forgets saved Wi-Fi networks, so tell the customer). Then check for a software update","quality":"best","feedback":"These rule out simple software causes without touching the customer''s photos or apps.","finding":"No change. Wi-Fi is still greyed out and Bluetooth still won''t start."},{"id":"mac","label":"Check whether the Wi-Fi MAC address shows in the phone''s status information","quality":"ok","feedback":"A useful clue that the Wi-Fi hardware isn''t being detected, but do the simple software checks first.","finding":"The Wi-Fi MAC address shows as unavailable."},{"id":"factory-reset","label":"Factory reset the phone","quality":"poor","feedback":"That erases the customer''s data. Save it for later, if at all, and only with a backup and their agreement. Less drastic checks come first."}]'::jsonb),
  ('no-wifi', 2, 'first-test', 'What''s your first check on the board?', '[{"id":"supply","label":"Inspect the Wi-Fi/Bluetooth area under magnification, then, with the phone on, check the IC''s supply against the schematic","quality":"best","feedback":"Look first, then confirm power. Checking against the schematic means you compare with the right expected value for this design.","finding":"No obvious damage at first glance. The Wi-Fi/Bluetooth IC''s supply is present and matches the known-good board.","reading":{"label":"Wi-Fi/Bluetooth IC supply, phone on","value":"Present","reference":"Known-good board: present and comparable"}},{"id":"remove-ic","label":"Remove the Wi-Fi IC to inspect underneath","quality":"poor","feedback":"Too early and risky. You haven''t checked whether the IC is getting what it needs to start."}]'::jsonb),
  ('no-wifi', 3, 'interpret', 'What does that tell you?', '[{"id":"power-only","label":"Power is fine, but the IC also needs a running clock and a released reset. It isn''t proven faulty yet","quality":"best","feedback":"Exactly. With power confirmed, the clock and reset are the next things to check before the IC itself.","interpretation":{"supports":"The IC is powered.","doesNotProve":"That the IC is faulty. It may be missing its clock or be held in reset.","remaining":["No clock reaching the IC","Reset line stuck","A damaged connection between the IC and the SoC","The IC itself","Less likely now: firmware or calibration data"]}},{"id":"ic-dead","label":"The supply''s fine, so the IC must be dead","quality":"poor","feedback":"A powered IC can still fail to start without its clock or with its reset stuck. Check those before condemning it."}]'::jsonb),
  ('no-wifi', 4, 'circuit', 'If the IC''s clock were missing, what could cause it?', '[{"id":"crystal-caps-ic","label":"The crystal, its load capacitors, or the oscillator circuit inside the Wi-Fi IC","quality":"best","feedback":"Right. A passive crystal needs the chip''s oscillator circuit to run, so all three are suspects."},{"id":"pmic-display","label":"The display supply from the PMIC","quality":"poor","feedback":"The display supply has nothing to do with the Wi-Fi IC''s clock. Stay on the circuit around the IC."}]'::jsonb),
  ('no-wifi', 5, 'clock', 'How do you check the clock?', '[{"id":"scope","label":"Use an oscilloscope with a 10× probe at the IC''s clock input, or a buffered clock point if the schematic shows one","quality":"best","feedback":"Only an oscilloscope shows whether the clock is running. The 10× probe adds less load, so it''s less likely to disturb the oscillator.","finding":"There is no clock signal at the Wi-Fi IC.","reading":{"label":"Oscilloscope, Wi-Fi IC clock input","value":"No oscillation: flat line","reference":"Known-good board: steady clock signal"}},{"id":"multimeter","label":"Measure the clock line with a multimeter on DC voltage","quality":"poor","feedback":"A multimeter shows an average voltage. It can''t tell you whether a clock is oscillating, or at what frequency."}]'::jsonb),
  ('no-wifi', 6, 'source', 'What now?', '[{"id":"inspect-crystal","label":"Inspect the crystal and its load capacitors closely under higher magnification. Drops can crack crystals","quality":"best","feedback":"Follow the missing signal back to its source.","finding":"A hairline crack is visible on the crystal''s casing."},{"id":"replace-ic","label":"Replace the Wi-Fi IC","quality":"poor","feedback":"Without a clock, even a new IC won''t start. Find out why the clock is missing first."}]'::jsonb),
  ('no-wifi', 7, 'confirm', 'Before you replace anything, is there anything else to check?', '[{"id":"reset","label":"Check the IC''s reset line against the schematic, so power, clock and reset are all accounted for","quality":"best","feedback":"The crack explains the missing clock, but a drop can cause more than one fault. Checking reset now means you won''t be surprised after the repair.","finding":"The reset line is in the state the schematic expects."},{"id":"straight-to-crystal","label":"No, the crack explains it. Replace the crystal","quality":"ok","feedback":"Reasonable, and probably right. But checking reset costs a minute and avoids a second trip if the drop did more damage."}]'::jsonb),
  ('no-wifi', 8, 'repair', 'How do you repair it?', '[{"id":"exact-crystal","label":"Fit a crystal of the exact frequency and specification from the parts list, with careful heat control, then check with the scope that the clock is now present","quality":"best","feedback":"The right part, fitted carefully, and the clock checked straight away. Seeing it return confirms the crystal was the cause.","finding":"A clock is now present at the Wi-Fi IC."},{"id":"any-crystal","label":"Fit any crystal with the same footprint","quality":"poor","feedback":"Same size doesn''t mean same part. A different frequency or load capacitance may not run, or may run off-frequency and cause unreliable Wi-Fi."},{"id":"both","label":"Replace the crystal and the Wi-Fi IC together, to be safe","quality":"poor","feedback":"Nothing points at the IC. Replacing parts without evidence adds risk and cost, and hides what actually fixed it."}]'::jsonb),
  ('no-wifi', 9, 'verify', 'What do you check before returning the phone?', '[{"id":"full-check","label":"Wi-Fi switches on, connects and transfers data; Bluetooth pairs; the MAC address shows; retest once the phone is warm; and calls and mobile data still work","quality":"best","feedback":"That confirms both failed features work, the IC is detected, it stays stable when warm, and nothing else was disturbed.","finding":"Wi-Fi and Bluetooth work, the MAC address shows, and everything stays stable when warm.","next":"end"},{"id":"switch-on","label":"The Wi-Fi switch turns on, so it''s fixed","quality":"poor","feedback":"A switch that turns on isn''t the same as working Wi-Fi. Test a real connection, Bluetooth, and stability when warm."}]'::jsonb)
